import{_ as s,o as t,c as a,a6 as n}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Questions fréquentes","description":"","frontmatter":{"title":"Questions fréquentes","docId":"user.preferences.faq","translationKey":"user.preferences.faq","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"efa3a64ab4d688fd7650801112a8d3200f2d685b223735f39c9163dbf095e6c4","translationRevision":"836077511b63d50cb31b00e7b6f42c14a7358d98ccbebce79e0db96d0bd70fde","order":40},"headers":[],"relativePath":"fr/user/preferences/faq.md","filePath":"fr/user/preferences/faq.md","lastUpdated":1794611623000}'),i={name:"fr/user/preferences/faq.md"};function r(o,e,l,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Questions fréquentes <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Questions fréquentes {#frequently-asked-questions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Résoudre les confusions courantes d’utilisation avant de modifier des données ou identifiants. L’application de bureau doit être lancée pour les vérifications ci-dessous ; les <a href="./../requirements.html">prérequis</a> décrivent les paquets pris en charge. Les fonctions locales présentées sont disponibles sauf mention d’une limite expérimentale ou dépendante d’un service.</p><h2 id="does-cloud-sign-in-connect-tiktok" tabindex="-1">La connexion Cloud connecte-t-elle TikTok ? <a class="header-anchor" href="#does-cloud-sign-in-connect-tiktok" aria-label="Permalink to &quot;La connexion Cloud connecte-t-elle TikTok ? {#does-cloud-sign-in-connect-tiktok}&quot;">​</a></h2><p>Non. Ouvrez <a href="./../live/connections.html">Connections</a>, choisissez un créateur et démarrez le LIVE séparément. L’identité Cloud sert aux services liés au compte. Un cookie TikTok doit uniquement être saisi dans le champ de connexion masqué prévu.</p><h2 id="why-is-a-connected-feed-empty" tabindex="-1">Pourquoi un flux connecté est-il vide ? <a class="header-anchor" href="#why-is-a-connected-feed-empty" aria-label="Permalink to &quot;Pourquoi un flux connecté est-il vide ? {#why-is-a-connected-feed-empty}&quot;">​</a></h2><p>Une salle calme peut n’avoir aucun nouvel événement. Choisissez tous les événements, effacez la recherche et reprenez le défilement, puis examinez l’état de connexion. Suspendre le défilement laisse l’ingestion et les automatisations fonctionner. Effacer le flux ne réinitialise ni les points ni les statistiques persistantes.</p><h2 id="are-statistics-only-for-this-session" tabindex="-1">Les statistiques concernent-elles uniquement cette session ? <a class="header-anchor" href="#are-statistics-only-for-this-session" aria-label="Permalink to &quot;Les statistiques concernent-elles uniquement cette session ? {#are-statistics-only-for-this-session}&quot;">​</a></h2><p>La <a href="./../points/statistics.html">page Analytics</a> actuelle interroge des agrégats persistants pour le créateur et la période sélectionnés. Élargissez les dates et actualisez pour consulter l’historique enregistré. Ce n’est pas une transcription complète des discussions. Les soldes de points suivent d’autres règles et peuvent inclure des ajustements manuels ou d’automatisation.</p><h2 id="where-are-templates-variables-and-rankings" tabindex="-1">Où se trouvent les modèles, variables et classements ? <a class="header-anchor" href="#where-are-templates-variables-and-rankings" aria-label="Permalink to &quot;Où se trouvent les modèles, variables et classements ? {#where-are-templates-variables-and-rankings}&quot;">​</a></h2><p>Les modèles et profils se trouvent dans <a href="./../automations/templates.html">Automations</a> ; Plugins Explore demande des plugins. Les valeurs d’exécution se trouvent dans Automations Variables. L’espace expérimental Rankings conserve <code>#/rankings</code>, mais il est masqué dans la navigation principale et la restauration au démarrage. Les classements de points ordinaires et les panneaux de classement du flux restent des vues distinctes.</p><h2 id="does-saving-synchronize-everything" tabindex="-1">L’enregistrement synchronise-t-il tout ? <a class="header-anchor" href="#does-saving-synchronize-everything" aria-label="Permalink to &quot;L’enregistrement synchronise-t-il tout ? {#does-saving-synchronize-everything}&quot;">​</a></h2><p>Non. Events/Actions Changes compare une référence locale. L’enregistrement des Variables reste local, avec des opérations distinctes d’envoi/adoption/retrait avec examen lorsqu’elles sont prises en charge. Les comparaisons de secrets sont masquées. Les incrustations Cloud utilisent création/révision et bibliothèque ; cette version n’a pas d’adaptateur Changes partagé pour les incrustations. Lisez <a href="./../cloud/changes.html">Changes</a> avant de choisir une direction.</p><h2 id="are-tests-harmless-and-do-imports-run-immediately" tabindex="-1">Les tests sont-ils sans effet, et les importations s’exécutent-elles immédiatement ? <a class="header-anchor" href="#are-tests-harmless-and-do-imports-run-immediately" aria-label="Permalink to &quot;Les tests sont-ils sans effet, et les importations s’exécutent-elles immédiatement ? {#are-tests-harmless-and-do-imports-run-immediately}&quot;">​</a></h2><p>Les tests peuvent exécuter des effets, notamment de l’audio, des requêtes réseau et des modifications de points. Commencez par <a href="./../automations/first-rule.html">core.log</a>. Les définitions importées restent désactivées ; examinez-les et activez-les explicitement. Installer un plugin nécessite aussi de configurer son service avant que ses actions puissent fonctionner.</p><h2 id="expected-result-and-recovery" tabindex="-1">Résultat attendu et récupération <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;Résultat attendu et récupération {#expected-result-and-recovery}&quot;">​</a></h2><p>Ces vérifications doivent identifier la page responsable sans réinitialisation. Les recherches automatiques de mises à jour sont facultatives ; l’installation est expérimentale et désactivée par les conditions de publication actuelles. La collaboration distante complète et la recherche de pseudonymes en production dépendent encore du déploiement et de la validation. Si le doute persiste, préservez vos données par des <a href="./backups.html">sauvegardes</a> et recueillez un <a href="./troubleshooting.html">rapport de diagnostic</a> avec version, heure et étapes de reproduction.</p>',17)])])}const h=s(i,[["render",r]]);export{m as __pageData,h as default};
